//! Arabic presentation forms (U+FB50..U+FDFF, U+FE70..U+FEFF) and the letters they
//! stand for: their compatibility decompositions (the space before an isolated haraka
//! dropped), Unicode 15.1.0. Generated with Python's `unicodedata`; forms without one
//! (and the BOM) are left out.

/// The letters an Arabic presentation form stands for, or None.
pub(crate) fn arabic_letters(c: char) -> Option<&'static str> {
    let c = u32::from(c);
    if !(0xFB50..=0xFEFF).contains(&c) {
        return None;
    }
    FORMS.binary_search_by_key(&c, |&(code, _)| code).ok().map(|i| FORMS[i].1)
}

