#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn forms_fold_to_letters() {
        assert_eq!(arabic_letters('\u{FEDF}'), Some("\u{644}"), "lam initial");
        assert_eq!(arabic_letters('\u{FEFB}'), Some("\u{644}\u{627}"), "lam-alef ligature");
        assert_eq!(arabic_letters('\u{FE70}'), Some("\u{64B}"), "isolated fathatan, no space");
        assert_eq!(arabic_letters('\u{627}'), None);
        assert_eq!(arabic_letters('\u{FEFF}'), None);
    }
}
